-- Pracownicy z pensją powyżej średniej działu
select /*+ index(e emp_dept_ix) */ e.ename, d.dname,
       to_char(e.hiredate, 'YYYY-MM-DD') as hired, nvl(e.comm, 0) + 100.5 as bonus
  from emp e join dept d on d.deptno = e.deptno
 where e.sal > (select avg(sal) from emp where deptno = :dept);

begin
  dbms_output.put_line('Gotowe: ' || to_char(sysdate, 'HH24:MI'));
end;
